static u32 app39_bit_count(s32 bit) noexcept {
    return static_cast<u32>(static_cast<u8>(bit%32))&31u;
}
static u32 app39_bit_addr(s32 bit) noexcept {
    return 0x22200u+static_cast<u32>(app39_bit_word(bit)*4);
}

