        const u32 h=static_cast<u32>(heading);
        const u32 sin_factor=load_le32(dg(m,load_le32(dg(m,0xC664u))+h*4u));
        const u32 cos_factor=load_le32(dg(m,load_le32(dg(m,0xC65Cu))+h*4u));
